pub struct WorkspaceRecord {
    pub id: String,
    pub name: String,
    pub path: String,
    pub one_off_chat: bool,
    pub archived: bool,
    pub created_at: i64,
    pub last_opened_at: i64,
    #[serde(default)]
    pub yolo: bool,
    #[serde(default)]
    pub default_provider: Option<String>,
    #[serde(default)]
    pub default_model: Option<String>,
    #[serde(default)]
    pub default_preferred_child_model: Option<String>,
    #[serde(default)]
    pub default_child_model_routing_mode: Option<String>,
    #[serde(default)]
    pub default_preferred_child_model_ref: Option<String>,
    #[serde(default)]
    pub default_allowed_child_model_refs: Vec<String>,
    #[serde(default)]
    pub default_enable_mcp: bool,
    #[serde(default)]
    pub default_backups_enabled: bool,
    #[serde(default)]
    pub provider_options: Option<Value>,
    #[serde(default)]
    pub user_name: Option<String>,
    #[serde(default)]
    pub user_profile: Option<Value>,
    #[serde(default)]
    pub defaults: Value,
}

impl WorkspaceRecord {
    pub fn new(
        id: impl Into<String>,
        name: impl Into<String>,
        path: impl Into<String>,
        now_ms: i64,
    ) -> Self {
        Self {
            id: id.into(),
            name: name.into(),
            path: path.into(),
            created_at: now_ms,
            last_opened_at: now_ms,
            default_enable_mcp: true,
            default_backups_enabled: true,
            defaults: Value::Object(Map::new()),
            ..Self::default()
        }
    }
}

